const cds = require ('../../index')

// Share model config with java in csn.meta.env
cds.on ('compile.for.runtime', csn => {
  const meta = csn.meta ??= {}
  const env = meta.env ??= {}
  const models = {}
  for (let each in cds.requires) {
    const r = cds.requires[each]
    if (r?.model_kind === 'embeddings') models[each] = r
  }
  env.profiles ??= cds.env.profiles
  env.embeddings = { models }
})

// Fill in missing models in calls to vector_embedding()
cds.on ('compile.to.dbx', dsn => {
  if (dsn.definitions) for (let d of Object.values(dsn.definitions)) {
    if (d.kind === 'entity' && d.elements) for (let e of Object.values(d.elements)) {
      if (e.value?.func === 'vector_embedding' && e.value.args.length < 3) {
        const model = cds.requires[e['@cds.embeddings.model']]?.model || cds.requires.embeddings.model
        if (e.value.args.length < 2) e.value.args.push({val:'DOCUMENT'})
        e.value.args.push ({val:model})
      }
    }
  }
})
